"""JSON repair utilities (handles malformed JSON generated by LLMs)."""

from __future__ import annotations

import json
from typing import Any


def repair_json(json_str: str) -> str:
    """Try to fix a common LLM JSON error: unescaped double quotes inside string values."""
    result: list[str] = []
    i = 0
    in_string = False

    while i < len(json_str):
        c = json_str[i]

        if not in_string:
            if c == '"':
                in_string = True
            result.append(c)
            i += 1
            continue

        if c == "\\":
            result.append(c)
            if i + 1 < len(json_str):
                result.append(json_str[i + 1])
                i += 2
            else:
                i += 1
            continue

        if c == '"':
            j = i + 1
            while j < len(json_str) and json_str[j] in " \t\n\r":
                j += 1
            if j >= len(json_str) or json_str[j] in ",:}]":
                in_string = False
                result.append(c)
                i += 1
                continue
            else:
                result.append('\\"')
                i += 1
                continue

        result.append(c)
        i += 1

    return "".join(result)


def safe_json_loads(raw: str) -> dict[str, Any]:
    """Safely parse JSON, automatically repairing common LLM formatting errors."""
    try:
        return json.loads(raw)
    except json.JSONDecodeError:
        pass
    repaired = repair_json(raw)
    try:
        return json.loads(repaired)
    except json.JSONDecodeError as e:
        raise ValueError(
            f"JSON parsing failed (still unparseable after repair): {e}\n"
            f"Original: {raw[:200]}\nRepaired: {repaired[:200]}"
        )
